#include <iostream>
#include <string>
#include <iomanip>

using namespace std;

class RDFSmartPlanner {
public:
    // Core Application Variables
        string groupName;
            string groupType;
                string projectDesc;
                    int memberCount;
                        
                            // Financial Variables
                                double localCash;
                                    int laborers;
                                        int laborDays;
                                            double buildingMaterials;
                                                double equipment;
                                                    double contractorAdvisory;
                                                        
                                                            // Business Plan Variables (Form Page 7 & 8)
                                                                double unitsPerMonth;
                                                                    double pricePerUnit;
                                                                        double transportCost;
                                                                            double operationalLabour;
                                                                                double otherExpenditures;
                                                                                    
                                                                                        string targetMarket;
                                                                                            string managerExperience;
                                                                                                string maintenanceFundStrategy;
                                                                                                    double yearlyMaintenanceCost;

                                                                                                        const double DAILY_LABOR_RATE = 65.00; // E65/day/pp (Page 6)

                                                                                                            // Helper to handle string inputs smoothly with spaces
                                                                                                                void getInputString(string &inputVar) {
                                                                                                                        cin.get(); // Clear buffer
                                                                                                                                getline(cin, inputVar);
                                                                                                                                    }

                                                                                                                                        void runPlanner() {
                                                                                                                                                cout << "==================================================\n";
                                                                                                                                                        cout << "    ESWATINI REGIONAL DEVELOPMENT FUND (RDF)       \n";
                                                                                                                                                                cout << "          SMART INTERACTIVE PLANNER               \n";
                                                                                                                                                                        cout << "            FORM STANDARDS: MNZ 1004              \n";
                                                                                                                                                                                cout << "==================================================\n\n";

                                                                                                                                                                                        // ---- STEP 1: INTERACTIVE DATA CAPTURE ----
                                                                                                                                                                                                cout << "[1/4] PARTICULARS OF APPLICANT\n";
                                                                                                                                                                                                        cout << "Enter Name of the Swazi Organized Group: ";
                                                                                                                                                                                                                getline(cin, groupName);
                                                                                                                                                                                                                        cout << "Enter Type of Group (e.g., Co-operative, Association, Company): ";
                                                                                                                                                                                                                                getline(cin, groupType);
                                                                                                                                                                                                                                        cout << "Enter Total Number of Registered Members: ";
                                                                                                                                                                                                                                                cin >> memberCount;

                                                                                                                                                                                                                                                        cout << "\n[2/4] PROJECT CLASSIFICATION & DESCRIPTION\n";
                                                                                                                                                                                                                                                                cout << "Enter a short description of the project (e.g., Poultry Production): ";
                                                                                                                                                                                                                                                                        getInputString(projectDesc);

                                                                                                                                                                                                                                                                                cout << "\n[3/4] FINANCIAL BREAKDOWN (PROPOSAL COSTS)\n";
                                                                                                                                                                                                                                                                                        cout << "Enter Cash amount community has saved/spent (E): ";
                                                                                                                                                                                                                                                                                                cin >> localCash;
                                                                                                                                                                                                                                                                                                        cout << "Enter number of community members donating free labor: ";
                                                                                                                                                                                                                                                                                                                cin >> laborers;
                                                                                                                                                                                                                                                                                                                        cout << "Enter average number of days each member will volunteer: ";
                                                                                                                                                                                                                                                                                                                                cin >> laborDays;
                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                cout << "\n--- Requested Funding from RDF ---\n";
                                                                                                                                                                                                                                                                                                                                                        cout << "Estimated Building Materials Cost (E): ";
                                                                                                                                                                                                                                                                                                                                                                cin >> buildingMaterials;
                                                                                                                                                                                                                                                                                                                                                                        cout << "Estimated Equipment and Fittings Cost (E): ";
                                                                                                                                                                                                                                                                                                                                                                                cin >> equipment;
                                                                                                                                                                                                                                                                                                                                                                                        cout << "Estimated Contractors / Training / Advisory Cost (E): ";
                                                                                                                                                                                                                                                                                                                                                                                                cin >> contractorAdvisory;

                                                                                                                                                                                                                                                                                                                                                                                                        cout << "\n[4/4] BUSINESS PLAN & SUSTAINABILITY DATA\n";
                                                                                                                                                                                                                                                                                                                                                                                                                cout << "Estimated production volume (Units/Products sold per month): ";
                                                                                                                                                                                                                                                                                                                                                                                                                        cin >> unitsPerMonth;
                                                                                                                                                                                                                                                                                                                                                                                                                                cout << "Selling Price per single unit (E): ";
                                                                                                                                                                                                                                                                                                                                                                                                                                        cin >> pricePerUnit;
                                                                                                                                                                                                                                                                                                                                                                                                                                                cout << "Estimated monthly Transport Costs (E): ";
                                                                                                                                                                                                                                                                                                                                                                                                                                                        cin >> transportCost;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                cout << "Estimated monthly running Labour Costs (E): ";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        cin >> operationalLabour;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                cout << "Estimated other monthly operational expenses (E): ";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        cin >> otherExpenditures;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        cout << "Describe your Target Market (Who will buy your product/service?): ";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                getInputString(targetMarket);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        cout << "Who will manage the project? State their experience/qualifications: ";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                getline(cin, managerExperience);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        cout << "How will you raise continuous funds for long-term maintenance?: ";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                getline(cin, maintenanceFundStrategy);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        cout << "Estimated total Maintenance & Repair Cost per year (E): ";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                cin >> yearlyMaintenanceCost;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // ---- STEP 2: COMPLIANCE AND SUCCESS VALIDATION ----
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                cout << "\n\n==================================================\n";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        cout << "             VERIFYING ELIGIBILITY...             \n";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                cout << "==================================================\n";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        bool eligible = true;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Rule 1: Member Limit check (Page 14)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (memberCount < 10) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    cout << "[-] CRITICAL FAILURE: Group has " << memberCount << " members. Form MNZ 1004 requires a minimum of 10 members to clear the Inkhundla level.\n";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                eligible = false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Financial Math Calculations
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        double laborValue = laborers * laborDays * DAILY_LABOR_RATE;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                double totalLocalContribution = localCash + laborValue;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        double totalRequestedFromRDF = buildingMaterials + equipment + contractorAdvisory;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                double grandTotalProjectCost = totalLocalContribution + totalRequestedFromRDF;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                double communityPercentage = (totalLocalContribution / grandTotalProjectCost) * 100;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        double rdfPercentage = (totalRequestedFromRDF / grandTotalProjectCost) * 100;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Rule 2: 10% Contribution Validation (Page 6)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (communityPercentage < 10.0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    double deficit = (grandTotalProjectCost * 0.10) - totalLocalContribution;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                cout << "[-] CRITICAL FAILURE: Your community contribution is only " << fixed << setprecision(2) << communityPercentage << "%.\n";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            cout << "    You must raise an additional E" << deficit << " in local value or cash to hit the 10% legal threshold.\n";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        eligible = false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // Business Viability Check (Page 7 Profitability)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                double grossMonthlyIncome = unitsPerMonth * pricePerUnit;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        double totalMonthlyExpenditure = transportCost + operationalLabour + otherExpenditures;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                double netMonthlyProfit = grossMonthlyIncome - totalMonthlyExpenditure;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (netMonthlyProfit <= 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    cout << "[-] WARNING: Business model is currently unprofitable. Monthly expenses (E" << totalMonthlyExpenditure << ") exceed projected income (E" << grossMonthlyIncome << ").\n";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                eligible = false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (!eligible) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            cout << "\n==================================================\n";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        cout << "  APPLICATION UNVIABLE. FIX ERRORS FLAGGED ABOVE. \n";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    cout << "==================================================\n";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return; 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // ---- STEP 3: GENERATING THE COMPLETED BUSINESS PLAN ----
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        cout << "[+] SUCCESS: CRITERIA PASSED! Generating Business Plan...\n\n";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        cout << "==================================================\n";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                cout << "      FORM MNZ 1004 GENERATED BUSINESS PLAN       \n";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        cout << "  (Copy text below into Section 6.0 & 7.0 of Form) \n";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                cout << "==================================================\n\n";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        cout << "6.0 DETAILS OF INCOME AND EXPENDITURE FOR " << groupName << "\n";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                cout << "------------------------------------------------------------------\n";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        cout << left << setw(30) << "INCOME" << setw(15) << "Units" << setw(15) << "Price/Unit" << "Total Sales/Month\n";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                cout << left << setw(30) << projectDesc << setw(15) << unitsPerMonth << "E" << setw(14) << pricePerUnit << "E" << grossMonthlyIncome << "\n\n";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        cout << left << setw(45) << "EXPENDITURE" << "Amount (E)\n";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                cout << left << setw(45) << "Transport Cost:" << "E" << transportCost << "\n";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        cout << left << setw(45) << "Labour Cost:" << "E" << operationalLabour << "\n";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                cout << left << setw(45) << "Others (Operating Overhead):" << "E" << otherExpenditures << "\n";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        cout << "------------------------------------------------------------------\n";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                cout << left << setw(45) << "TOTAL EXPENDITURE:" << "E" << totalMonthlyExpenditure << "\n";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        cout << left << setw(45) << "PROJECTED NET MONTHLY NET PROFIT:" << "E" << netMonthlyProfit << "\n";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                cout << "------------------------------------------------------------------\n\n";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        cout << "6.1 WHAT IS YOUR MARKET?\n";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                cout << ">> " << targetMarket << "\n\n";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        cout << "6.2 DO YOU HAVE ANY SALES AGREEMENT WITH YOUR MARKET?\n";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                cout << ">> Yes, letters of intent/market analysis from target buyers will be attached securely to this business profile.\n\n";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        cout << "7.0 PROJECT MAINTENANCE AND REPAIR\n";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                cout << "------------------------------------------------------------------\n";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        cout << "7.1 WHO WILL OPERATE OR MANAGE THE PROJECT AFTER ITS COMPLETION?\n";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                cout << ">> " << managerExperience << "\n\n";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        cout << "7.3 HOW WILL YOU RAISE THE FUNDS FOR MAINTENANCE?\n";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                cout << ">> " << maintenanceFundStrategy << " (Retaining portion of the E" << netMonthlyProfit << " monthly profits to offset costs).\n\n";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        cout << "7.4 WHAT WILL BE THE TOTAL COST PER YEAR?\n";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                cout << ">> E" << yearlyMaintenanceCost << " per annum.\n";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        cout << "==================================================\n";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            int main() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                RDFSmartPlanner planner;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    planner.runPlanner();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        